// ヘルパー関数: 重み付きランダム選択
export const weightedRandomSelect = (items) => {
  const totalWeight = items.reduce((sum, item) => sum + item.weight, 0);
  let random = Math.random() * totalWeight;

  for (const item of items) {
    random -= item.weight;
    if (random <= 0) {
      return item.name;
    }
  }

  return items[items.length - 1].name;
};

// ランダムな姓を取得
export function getRandomSurname() {
  return weightedRandomSelect(PLAYER_NAMES.surnames);
}

// ランダムな名を取得
export function getRandomGivenName() {
  return weightedRandomSelect(PLAYER_NAMES.givenNames);
}

// フルネームを生成
export function generateRandomPlayerName() {
  return getRandomSurname() + ' ' + getRandomGivenName();
}
